def longest_calm(readings):
    last = {}
    start = 0
    best = 0
    for i, ch in enumerate(readings):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        best = max(best, i - start + 1)
    return best

